import{_ as i,l as n,o as e,c as o,v as l,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"自奖励语言模型","description":"","frontmatter":{"title":"自奖励语言模型","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-rewarding-lm.md","filePath":"llm/self-rewarding-lm.md","lastUpdated":1789023840000}'),A={name:"llm/self-rewarding-lm.md"};function E(m,a,c,_,u,f){const t=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=l('<h1 id="自奖励语言模型" tabindex="-1">自奖励语言模型 <a class="header-anchor" href="#自奖励语言模型" aria-label="Permalink to &quot;自奖励语言模型&quot;">​</a></h1><div class="epigraph"><p>同一模型既生成候选，又给候选打分，用自己的序做迭代 DPO——监督闭环，偏见也闭环。</p><footer>—— Yuan 等，Self-Rewarding Language Models</footer></div><p><a href="/llm/iterative-online-dpo">上一课</a>用外部裁判造新对。缺口是：<strong>外部 GPT-4 / 人类仍然贵，规模化会停。</strong> Yuan 等人让模型扮演 LLM-as-judge 给自己的完成打分，再用这些对做迭代 DPO，称为自奖励语言模型。本课写闭环，对照 <a href="/llm/llm-judge-reward">LLM 裁判</a> 的偏差在自指时如何放大。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>迭代 DPO 的瓶颈是每轮标注。若模型已经能按原则打分（宪法式、细则），可以把 JUD 换成 \\(\\pi\\) 自己。希望是：能力上升 → 裁判也变好 → 数据变好，正循环。风险是：自偏爱（Zheng 等已量过）让模型给自己的风格打高分，正循环变成自夸循环。没有外部金标，曲线无法区分两种。</p><p>Yuan 等用 Llama-2-70B 一类指令模型，提示它输出分数，造对，多轮 DPO，报告指令遵循提升。这是存在性结果，不是「可以去掉所有人类」。人类仍写原则、做抽检。</p><h3 id="生成器与裁判权是否分离" tabindex="-1">生成器与裁判权是否分离 <a class="header-anchor" href="#生成器与裁判权是否分离" aria-label="Permalink to &quot;生成器与裁判权是否分离&quot;">​</a></h3><p>同一套权重、同一提示族，裁判不是独立证据。最低限度：打分时用固定的评判提示、禁止看见「这是我生成的」身份；更好：用稍旧的 checkpoint 当裁判，减少即时自夸。完全独立的裁判模型回到上一课。</p><p><span class="marginnote">自奖励不是可验证奖励。数学对错仍应走校验器，不要让模型给自己的证明打 5 分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每轮：当前 \\(\\pi\\) 采样 \\(K\\) 条 → 同一 \\(\\pi\\)（或上一轮）按评判提示打分 → 选 \\(y_w,y_l\\) → DPO → 可选更新评判提示。监控：外部 Arena / 人类胜率、长度、自偏爱探针（把别人的完成伪装成自己）。分数校准（本课程 RM 校准课）对口头打分几乎不做数，应用成对胜负而不是绝对分。</p>',11)),(e(),s(h,null,{default:r(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%22%E7%AD%96%E7%95%A5%20%CF%80%22%5D%20--%3E%20Y%5B%22%E9%87%87%E6%A0%B7%E5%80%99%E9%80%89%22%5D%0A%20%20PI%20--%3E%20J%5B%22%E5%90%8C%E4%B8%80%20%CF%80%20%E5%BD%93%E8%A3%81%E5%88%A4%22%5D%0A%20%20Y%20--%3E%20J%0A%20%20J%20--%3E%20PAIR%5B%22%E8%87%AA%E9%80%A0%E5%81%8F%E5%A5%BD%E5%AF%B9%22%5D%0A%20%20PAIR%20--%3E%20DPO%5B%22%E8%BF%AD%E4%BB%A3%20DPO%22%5D%0A%20%20DPO%20--%3E%20PI%0A%20%20EXT%5B%22%E5%A4%96%E9%83%A8%E9%87%91%E6%A0%87%E6%8A%BD%E6%A3%80%22%5D%20--%3E%20GATE%5B%22%E9%98%B2%E8%87%AA%E5%A4%B8%E5%BE%AA%E7%8E%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>与 <a href="/llm/process-supervision">过程监督</a> 结合：自奖励只打过程评语，终点仍校验器，可部分打破闭环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>闭环改变数据分布的速度比固定 RM 更快，因为裁判与策略共移。共移在「真变好」与「共同黑客细则」上不可辨。外部金标是唯一辨识器。长度偏爱在自奖励里往往更强：模型既爱写长也爱给长打高分。必须控长评测。</p><p><span class="marginnote">宪法式 CAI 的比较器通常是固定教师，不是正在被 RL 的那份权。自奖励把教师也放开。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>安全轴不宜自奖励：有害完成可能被自我开脱。有用轴可试，必须抽检。可验证域用 GRPO，不要用自评分代替 \\(R\\)。下一课 Nash 学习从另一方向处理「谁当最优」：不是自己给自己打分，而是两人博弈的均衡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自奖励用当前模型当裁判造对，做迭代 DPO，去掉外部标注吞吐瓶颈。</li><li>自偏爱与共移黑客无法从代理分上区分，必须外部金标。</li><li>生成器与裁判至少用旧 checkpoint 或固定评判提示弱分离。</li><li>可验证域不要用自评分代替校验器。</li><li>出处：Yuan 等 Self-Rewarding Language Models；裁判偏差见 Zheng 等；CAI 对照 Bai 等。</li></ul>',8))])}const B=i(A,[["render",E]]);export{D as __pageData,B as default};
